package com.learn.hub.observability;

import io.micrometer.core.instrument.MeterRegistry;
import jakarta.servlet.FilterChain;
import jakarta.servlet.ServletException;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import org.slf4j.MDC;
import org.springframework.stereotype.Component;
import org.springframework.web.filter.OncePerRequestFilter;

import java.io.IOException;

/** traceId 落到日志与响应头，同时按模板化 URI 记录请求结果。 */
@Component
public class TraceAndMetricsFilter extends OncePerRequestFilter {

    private final MeterRegistry registry;

    public TraceAndMetricsFilter(MeterRegistry registry) { this.registry = registry; }

    @Override
    protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response,
                                    FilterChain chain) throws ServletException, IOException {
        if (MDC.get("traceId") != null) {
            response.setHeader("X-Trace-Id", MDC.get("traceId"));
        }
        try {
            chain.doFilter(request, response);
        } finally {
            // 模板化路径 + 状态码做标签，避免把原始 URI 写进标签造成基数爆炸
            String uri = request.getRequestURI().replaceAll("/\\d+", "/{id}");
            registry.counter("learnhub_http_requests_total",
                            "method", request.getMethod(), "uri", uri,
                            "status", String.valueOf(response.getStatus()))
                    .increment();
        }
    }
}
